create table if not exists public.order_installments (id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, installment_number integer not null, due_date date not null, amount_due numeric(18,2) not null, amount_paid numeric(18,2) not null default 0, balance numeric(18,2) generated always as (greatest(amount_due-amount_paid,0)) stored, status text not null default 'pending', payment_id uuid null references public.payments(id), payment_reference text null, paid_at timestamptz null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(order_id,installment_number), check(amount_due>=0), check(amount_paid>=0), check(amount_paid<=amount_due));
create index if not exists order_installments_order_idx on public.order_installments(order_id,installment_number);
create or replace function public.generate_order_installments(_order_id uuid,_months integer,_start_date date default current_date) returns void language plpgsql security definer set search_path=public as $$ declare o public.orders; i integer; base numeric; last numeric; due numeric; begin select * into o from public.orders where id=_order_id for update; if o.id is null then raise exception 'Order not found'; end if; if _months is null or _months<=0 then return; end if; if exists(select 1 from public.order_installments where order_id=_order_id) then return; end if; base:=round(o.total_amount/_months,2); last:=o.total_amount-(base*(_months-1)); for i in 1.._months loop due:=case when i=_months then last else base end; insert into public.order_installments(order_id,installment_number,due_date,amount_due) values(_order_id,i,(_start_date + ((i-1)*30)::integer),due); end loop; end; $$;
revoke all on function public.generate_order_installments(uuid,integer,date) from public; grant execute on function public.generate_order_installments(uuid,integer,date) to authenticated;
create or replace function public.sync_installment_from_payment() returns trigger language plpgsql security definer set search_path=public as $$ declare inst public.order_installments; pay numeric; remain numeric; begin if new.status not in ('approved','completed','paid','success') then return new; end if; if new.related_payment_id is null then return new; end if; select coalesce(p.total_amount,0)-coalesce(p.amount_paid,0) into pay from public.payments p where p.id=new.related_payment_id; if pay<=0 then return new; end if; select * into inst from public.order_installments where payment_id=new.related_payment_id or payment_reference=(select reference from public.payments where id=new.related_payment_id) order by installment_number limit 1; if inst.id is null then return new; end if; update public.order_installments set amount_paid=least(amount_due,amount_paid+pay),status=case when amount_paid+pay>=amount_due then 'paid' else 'partial' end, payment_id=new.related_payment_id,payment_reference=new.reference,paid_at=case when amount_paid+pay>=amount_due then now() else paid_at end,updated_at=now() where id=inst.id; return new; end; $$;
revoke all on function public.sync_installment_from_payment() from public; 
drop trigger if exists trg_sync_payment_request_state on public.payment_requests; create trigger trg_sync_payment_request_state after update of status on public.payment_requests for each row execute function public.sync_payment_request_state();
drop trigger if exists trg_sync_role_after_payment_change on public.payments; create trigger trg_sync_role_after_payment_change after insert or update on public.payments for each row execute function public.sync_role_after_payment_change();
